"use client";
// Imagen incorporada para evitar dependencias de rutas estáticas en el entorno Demo.
const PORTADA_WEBP = "";
import {APP_VERSION} from "@/lib/version";
import {useState} from "react";import {useRouter} from "next/navigation";
export default function LoginDemo({users}:{users:any[]}){const r=useRouter(),[id,setId]=useState(String(users[0]?.id||"")),[busy,setBusy]=useState(false);async function enter(){setBusy(true);const x=await fetch("/api/auth/login",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({user_id:Number(id)})});if(x.ok){r.push("/");r.refresh()}else{alert("No fue posible iniciar sesión");setBusy(false)}}return <div className="login-shell"><div className="login-brand login-brand-renovada" role="img" aria-label="Conecta Bancaribe: conecta necesidades, impulsa iniciativas y genera valor" style={{backgroundImage: `url(data:image/webp;base64,${PORTADA_WEBP})`, backgroundPosition:"center center", backgroundSize:"contain", backgroundRepeat:"no-repeat", backgroundColor:"#003f6b"}} /><div className="login-panel"><div className="w-full max-w-md"><div className="mb-8 lg:hidden text-2xl font-black italic text-[#003f6b]">BANCARIBE · <span className="text-[#08a5ad]">Conecta Bancaribe</span></div><h1 className="text-3xl font-black text-[#003f6b]">Iniciar sesión</h1><p className="text-slate-500 mt-1 mb-7">Accede a Conecta Bancaribe</p><label className="font-bold text-sm">Usuario<select className="input mt-2 h-12" value={id} onChange={e=>setId(e.target.value)}>{users.map(u=><option key={u.id} value={u.id}>{u.name} · {u.role_label} · {u.area}</option>)}</select></label><label className="font-bold text-sm block mt-5">Contraseña<div className="input mt-2 h-12 flex items-center text-slate-400">•••••••••••• <span className="ml-auto">◉</span></div></label><button onClick={enter} disabled={busy} className="w-full mt-6 rounded-lg bg-[#087df1] text-white py-3 font-black shadow-lg">{busy?"Ingresando…":"Ingresar  →"}</button><label className="flex gap-2 mt-5 text-sm"><input type="checkbox" defaultChecked/> Recordar mi usuario</label><div className="text-[#087df1] text-sm mt-3">¿Olvidaste tu contraseña?</div><div className="login-invite mt-7 rounded-xl p-4 flex gap-3 items-start"><span className="text-3xl" aria-hidden="true">✧</span><div><strong className="block text-[#003f6b] text-lg leading-tight">¡Conecta tus necesidades e iniciativas!</strong><p className="text-sm mt-2 text-[#003f6b]">Hazlas visibles, articula con las áreas clave y generemos juntos más valor.</p></div></div><p className="text-xs mt-6 text-slate-400">Prototipo: en producción este acceso se sustituirá por autenticación corporativa/SSO.</p><p className="text-xs mt-2 font-bold text-[#003f6b]">Conecta Bancaribe · {APP_VERSION}</p></div></div></div>}
